import os
import time
from typing import Any, Dict, List, Optional

import assemblyai as aai


def _extract_word_timestamps(result: Any) -> List[Dict[str, Any]]:
    words = []

    # AssemblyAI transcript objects commonly expose `words`, each with
    # `text`, `start`, `end`, and sometimes `confidence`.
    if hasattr(result, "words") and result.words:
        for w in result.words:
            words.append(
                {
                    "word": getattr(w, "text", None),
                    "start": getattr(w, "start", None),
                    "end": getattr(w, "end", None),
                    "confidence": getattr(w, "confidence", None),
                }
            )
        return words

    # Fallback for dict-like payloads.
    raw_words = None
    if isinstance(result, dict):
        raw_words = result.get("words") or result.get("utterances") or []
    elif hasattr(result, "__dict__"):
        raw_words = getattr(result, "words", None) or []

    for w in raw_words or []:
        if isinstance(w, dict):
            words.append(
                {
                    "word": w.get("text") or w.get("word"),
                    "start": w.get("start"),
                    "end": w.get("end"),
                    "confidence": w.get("confidence"),
                }
            )
        else:
            words.append(
                {
                    "word": getattr(w, "text", None) or getattr(w, "word", None),
                    "start": getattr(w, "start", None),
                    "end": getattr(w, "end", None),
                    "confidence": getattr(w, "confidence", None),
                }
            )

    return words


def _extract_segment_timestamps(result: Any) -> List[Dict[str, Any]]:
    segments = []

    # Prefer paragraphs/utterances as segment-like timestamp boundaries when available.
    segment_sources = []
    if hasattr(result, "utterances") and result.utterances:
        segment_sources = result.utterances
    elif hasattr(result, "paragraphs") and result.paragraphs:
        segment_sources = result.paragraphs
    elif isinstance(result, dict):
        segment_sources = result.get("utterances") or result.get("paragraphs") or []

    for seg in segment_sources:
        if isinstance(seg, dict):
            segments.append(
                {
                    "text": seg.get("text"),
                    "start": seg.get("start"),
                    "end": seg.get("end"),
                    "speaker": seg.get("speaker"),
                }
            )
        else:
            segments.append(
                {
                    "text": getattr(seg, "text", None),
                    "start": getattr(seg, "start", None),
                    "end": getattr(seg, "end", None),
                    "speaker": getattr(seg, "speaker", None),
                }
            )

    return segments


def transcribe_with_timestamps(
    audio_source: str,
    mode: str = "word",
    *,
    api_key: Optional[str] = None,
    polling_interval: float = 5.0,
    timeout_seconds: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """
    Transcribe an audio file or URL with AssemblyAI and return timestamps.

    Args:
        audio_source: Path to a local audio file or a public URL.
        mode: "word" for word-level timestamps, "segment" for segment-level timestamps.
        api_key: AssemblyAI API key; defaults to ASSEMBLYAI_API_KEY.
        polling_interval: Seconds between job status checks for async uploads.
        timeout_seconds: Optional maximum seconds to wait for completion.

    Returns:
        A list of dicts containing timestamps.
    """
    key = api_key or os.getenv("ASSEMBLYAI_API_KEY")
    if not key:
        raise ValueError("Missing AssemblyAI API key. Set ASSEMBLYAI_API_KEY or pass api_key.")

    aai.settings.api_key = key

    transcriber = aai.Transcriber(
        config=aai.TranscriptionConfig(
            punctuate=True,
            format_text=True,
            speaker_labels=True,
            word_boost=[],
            iab_categories=False,
            auto_highlights=False,
            sentiment_analysis=False,
        )
    )

    # AssemblyAI can transcribe URLs directly; local files are uploaded automatically by the SDK.
    transcript = transcriber.transcribe(audio_source)

    start_time = time.time()
    while getattr(transcript, "status", None) not in ("completed", "error", "failed"):
        if timeout_seconds is not None and (time.time() - start_time) > timeout_seconds:
            raise TimeoutError("Transcription timed out.")
        time.sleep(polling_interval)
        transcript = aai.Transcript.get(transcript.id)

    if getattr(transcript, "status", None) in ("error", "failed"):
        raise RuntimeError(f"Transcription failed: {getattr(transcript, 'error', 'unknown error')}")

    if mode.lower() == "word":
        return _extract_word_timestamps(transcript)
    if mode.lower() == "segment":
        return _extract_segment_timestamps(transcript)

    raise ValueError('mode must be either "word" or "segment"')
